def rule_short_docs_without_exhibit_section_tail(doc: dict) -> list[dict]:
    """Match the tail of short filings that contain no exhibit section so the model can answer none listed."""
    try:
        texts = doc.get("texts", [])
        if not texts:
            return []

        max_page = max((span.get("page_no") or 0) for span in texts)
        if max_page > 25:
            return []

        has_exhibit_anchor = False
        for span in texts:
            text = " ".join((span.get("text") or "").split()).lower()
            path = " ".join((((span.get("structure") or {}).get("path_text")) or "").split()).lower()
            blob = f"{path} {text}"
            if (
                "item 9.01" in blob
                or ("item 15" in blob and "exhibit" in blob)
                or ("item 16" in blob and "exhibit" in blob)
                or ("item 6" in blob and "exhibit" in blob)
                or "exhibit index" in blob
                or "index to exhibits" in blob
            ):
                has_exhibit_anchor = True
                break
        if has_exhibit_anchor:
            return []

        hits: list[dict] = []
        for span in texts:
            page_no = span.get("page_no") or 0
            text = " ".join((span.get("text") or "").split())
            if page_no < max(1, max_page - 1):
                continue
            if span.get("label") not in {"text", "section_header", "list_item"}:
                continue
            if not text or len(text) > 260:
                continue
            hits.append(span)
        return hits[-6:]
    except Exception:
        return []

def rule_tables_after_exhibit_index_headers(doc: dict) -> list[dict]:
    """Match tables that follow Exhibit Index, Index to Exhibits, or numbered Exhibits headers."""
    try:
        import re

        texts = doc.get("texts", [])
        hits: list[dict] = []
        seen: set[int] = set()

        def is_anchor(span: dict) -> bool:
            text = " ".join((span.get("text") or "").split()).lower()
            norm = re.sub(r"[^a-z0-9.]+", " ", text).strip()
            return (
                "exhibit index" in norm
                or "index to exhibits" in norm
                or norm in {"3. exhibits", "3 exhibits", "(3) exhibits", "2. exhibits", "2 exhibits", "(2) exhibits"}
            )

        def is_exhibit_table(span: dict) -> bool:
            text = " ".join((span.get("text") or "").split())
            return span.get("label") == "table" and (
                re.search(r"\bexhibit\s*(?:number|no\.?)\b", text, re.IGNORECASE)
                or re.search(r"\|\s*exhibit\s*\|\s*description\s*\|", text, re.IGNORECASE)
                or re.search(r"\|\s*exhibit number\s*\|\s*exhibit description\s*\|", text, re.IGNORECASE)
                or re.search(r"\|\s*no\.\s*\|\s*exhibit description\s*\|", text, re.IGNORECASE)
                or re.search(r"\|\s*\*{0,2}(?:10|4|99|104|3)\s*\.\s*\d", text)
            )

        for idx, span in enumerate(texts):
            if not is_anchor(span):
                continue
            anchor_page = span.get("page_no") or 0
            for j in range(idx + 1, min(len(texts), idx + 16)):
                candidate = texts[j]
                page_no = candidate.get("page_no") or 0
                if page_no and anchor_page and page_no - anchor_page > 4:
                    break
                if is_exhibit_table(candidate) and j not in seen:
                    hits.append(candidate)
                    seen.add(j)
        return hits
    except Exception:
        return []

def rule_early_8k_exhibit_neighbor_window(doc: dict) -> list[dict]:
    """Match short early-page 8-K spans around Item 9.01 exhibit headers and split exhibit rows."""
    try:
        import re

        texts = doc.get("texts", [])
        hits: list[dict] = []
        seen: set[int] = set()

        def add(idx: int) -> None:
            if 0 <= idx < len(texts) and idx not in seen:
                hits.append(texts[idx])
                seen.add(idx)

        def looks_like_exhibit_number(text: str) -> bool:
            return bool(re.fullmatch(r"\*{0,2}(?:\d{1,3})(?:\.\d+)*(?:[A-Z])?", text))

        for idx, span in enumerate(texts):
            page_no = span.get("page_no") or 0
            if page_no > 4:
                continue
            text = " ".join((span.get("text") or "").split())
            text_l = text.lower()
            path = " ".join((((span.get("structure") or {}).get("path_text")) or "").split()).lower()
            is_anchor = (
                "item 9.01" in text_l
                or "financial statements and exhibits" in text_l
                or re.fullmatch(r"\(?d\)?\.?\s+exhibits\.?", text_l)
                or "exhibit no" in text_l
                or "description of exhibit" in text_l
                or ("item 9.01" in path and ("exhibit no" in text_l or "description of exhibit" in text_l))
            )
            if not is_anchor:
                continue

            for j in range(idx, min(len(texts), idx + 6)):
                candidate = texts[j]
                cand_page = candidate.get("page_no") or 0
                if cand_page and page_no and cand_page != page_no:
                    break
                cand_text = " ".join((candidate.get("text") or "").split())
                cand_l = cand_text.lower()
                if not cand_text or len(cand_text) > 240:
                    continue
                if re.search(r"\bsignatures?\b", cand_l):
                    break
                if (
                    j == idx
                    or re.fullmatch(r"\(?d\)?\.?\s+exhibits\.?", cand_l)
                    or "exhibit no" in cand_l
                    or "description of exhibit" in cand_l
                    or looks_like_exhibit_number(cand_text)
                    or re.match(r"^\*{0,2}(?:exhibit\s*)?\d+(?:\.\d+)*(?:[A-Z])?\s*[:.]?\s+\S", cand_text, re.IGNORECASE)
                ):
                    add(j)
                    if looks_like_exhibit_number(cand_text) and j + 1 < len(texts):
                        next_text = " ".join((texts[j + 1].get("text") or "").split())
                        next_page = texts[j + 1].get("page_no") or 0
                        if (
                            next_text
                            and len(next_text) <= 240
                            and "signature" not in next_text.lower()
                            and (not next_page or next_page == page_no)
                        ):
                            add(j + 1)
        return hits
    except Exception:
        return []

def rule_early_8k_exhibit_tables(doc: dict) -> list[dict]:
    """Match page-1/4 8-K exhibit tables under Item 9.01 or nearby exhibit blocks."""
    try:
        import re

        texts = doc.get("texts", [])
        hits: list[dict] = []
        for idx, span in enumerate(texts):
            if span.get("label") != "table" or (span.get("page_no") or 99) > 4:
                continue

            text = " ".join((span.get("text") or "").split())
            path = " ".join((((span.get("structure") or {}).get("path_text")) or "").split()).lower()
            has_exhibit_header = (
                re.search(r"\bexhibit\s*(?:number|no\.?)\b", text, re.IGNORECASE)
                or re.search(r"\|\s*exhibit\s*\|\s*description\s*\|", text, re.IGNORECASE)
            )
            if not has_exhibit_header:
                continue

            nearby = " ".join(
                " ".join((texts[j].get("text") or "").split())
                for j in range(max(0, idx - 5), idx + 1)
                if (texts[j].get("page_no") or 99) <= 4
            ).lower()

            if "item 9.01" in path or "item 8.01" in path or "item 9.01" in nearby or "(d) exhibits" in nearby:
                hits.append(span)
        return hits
    except Exception:
        return []

def rule_tables_after_item15_or_item6_exhibits(doc: dict) -> list[dict]:
